import numpy as np

class WavySphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Base sphere function
        sphere = np.sum(x**2)

        # Add wavy components with different frequencies
        wavy = 0.0
        for i in range(self.dim):
            wavy += np.sin(5 * x[i]) + 0.5 * np.sin(10 * x[i])

        # Combine with scaling to maintain global minimum at origin
        return sphere + 0.1 * wavy
